/**
 * 설계 파이프라인의 순수 함수(design-pipeline.ts)를 Rust로 옮기면서(ADR-191 3o) JS와 Rust가 다르게 읽기 쉬운 입력을 고정한다.
 * 기대값은 옮기기 전 TS 구현이 낸 값이다(JSON.stringify 글자 — 키 순서 포함). 의도한 차이로 적은 벡터는 없다(짝 없는 서로게이트는 napi 경계에서 U+FFFD가 되지만 벡터에는 넣지 않았다).
 * 특수한 값은 표시 객체로 적는다: {"$num":"NaN"}(NaN·Infinity·-0), {"$undef":true}(undefined). 보이지 않는 글자는 \u 이스케이프로 적었다.
 *
 * 막는 검사(checkDesignApproval) 벡터는 "거의 같은" 거부 입력을 하나씩 넣는다: 요구사항 id `R-1` 대 `R-10`·`r-1`·` R-1`·`R-1 `·전각·ZWSP, 상태 `approved` 대
 * `Approved`·`approved `·`APPROVED`·키릴 а·빈 글자·글자가 아닌 값, 빈 목록, 승인된 기록의 망가진 id 목록(읽지 않는다). 경로(isDesignPipelineDocPath)는 접두·대소문자·`./`·`design//`·`designx`·`.MD`·
 * 줄 끝 글자·전각 숫자를 넣었다. 검토 독립성은 `unknown` 계열(대소문자·공백만 다른 값 포함)이 독립으로 읽히지 않음을 고정한다.
 */

interface Vector {
  fn: string;
  note: string;
  args: unknown[];
  expected?: unknown;
  throws?: true;
}

function revive(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(revive);
  if (value !== null && typeof value === 'object') {
    const record = value as Record<string, unknown>;
    if ('$num' in record) return Number(record['$num']);
    if ('$undef' in record) return undefined;
    return Object.fromEntries(Object.entries(record).map(([key, item]) => [key, revive(item)]));
  }
  return value;
}

