describe('design-pipeline 벡터(옛 TS 구현이 낸 값)', () => {
  for (const [index, vector] of VECTORS.entries()) {
    it(`${index} ${vector.fn}: ${vector.note}`, () => {
      const impl = IMPLS[vector.fn]!;
      const args = revive(vector.args) as unknown[];
      if (vector.throws) {
        expect(() => impl(...args)).toThrow();
        return;
      }
      const actual = impl(...args);
      const expected = revive(vector.expected);
      expect(JSON.stringify(actual)).toBe(JSON.stringify(expected));
      if (typeof expected === 'number') expect(Object.is(actual, expected)).toBe(true); // NaN·-0·Infinity 구별
    });
  }

  it('벡터가 비지 않았고 함수마다 있다', () => {
    expect(VECTORS.length).toBeGreaterThan(500);
    const names = new Set(VECTORS.map((vector) => vector.fn));
    for (const name of ['nextDesignPipelineDocNumber', 'designPipelineDocPath', 'designPipelineSidecarPath', 'isDesignPipelineDocPath', 'parseDesignBundlesTable', 'buildDesignPipelineRequestPrompt', 'buildDesignPipelineDocTemplate', 'checkDesignApproval', 'reviewIndependence', 'deriveDesignPipelineResult']) {
      expect(names.has(name), name).toBe(true);
    }
  });

  it('열린 쪽 거부 벡터를 충분히 담았다(승인 확인은 막는 쪽 기대값 수를 센다)', () => {
    const approval = VECTORS.filter((vector) => vector.fn === 'checkDesignApproval' && !vector.throws);
    const blocked = approval.filter((vector) => (vector.expected as { blocked: boolean }).blocked);
    expect(approval.length).toBeGreaterThan(60);
    expect(blocked.length).toBeGreaterThan(20);
    expect(approval.length - blocked.length).toBeGreaterThan(20);
  });
});
